create extension if not exists pgcrypto;
create table public.lojas(id uuid primary key default gen_random_uuid(),nome_fantasia text not null,cnpj text not null unique,endereco text not null default '',telefone text not null default '',created_at timestamptz not null default now());
create table public.operadores(id uuid primary key default gen_random_uuid(),loja_id uuid not null references public.lojas(id),auth_user_id uuid unique references auth.users(id),cpf char(11) not null,auth_email text not null unique,pin_hash text not null,nome text not null,ativo boolean not null default true,created_at timestamptz not null default now(),unique(loja_id,cpf));
create table public.produtos(id uuid primary key default gen_random_uuid(),loja_id uuid not null references public.lojas(id),nome text not null,descricao text not null default '',ativo boolean not null default true,created_at timestamptz not null default now(),unique(loja_id,id));
create table public.produto_variacoes(id uuid primary key default gen_random_uuid(),loja_id uuid not null references public.lojas(id),produto_id uuid not null,sku text not null,codigo_barras text,cor text not null,tamanho text not null,preco numeric(12,2) not null check(preco>=0),estoque integer not null default 0 check(estoque>=0),ativo boolean not null default true,created_at timestamptz not null default now(),foreign key(loja_id,produto_id) references public.produtos(loja_id,id),unique(loja_id,sku),unique(loja_id,codigo_barras));
create table public.clientes(id uuid primary key default gen_random_uuid(),loja_id uuid not null references public.lojas(id),cpf char(11) not null,nome text not null,email text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(loja_id,cpf));
create table public.carrinhos_ativos(id uuid primary key default gen_random_uuid(),loja_id uuid not null references public.lojas(id),operador_id uuid not null references public.operadores(id),status text not null default 'aberto' check(status in('aberto','finalizado','cancelado')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.carrinho_itens(id uuid primary key default gen_random_uuid(),carrinho_id uuid not null references public.carrinhos_ativos(id) on delete cascade,loja_id uuid not null references public.lojas(id),variacao_id uuid not null references public.produto_variacoes(id),quantidade integer not null check(quantidade>0),unique(carrinho_id,variacao_id));
create table public.vendas(id uuid primary key default gen_random_uuid(),loja_id uuid not null references public.lojas(id),operador_id uuid not null references public.operadores(id),cliente_id uuid references public.clientes(id),total numeric(12,2) not null check(total>=0),forma_pagamento text not null,created_at timestamptz not null default now(),origem_carrinho_id uuid unique references public.carrinhos_ativos(id));
create table public.venda_itens(id uuid primary key default gen_random_uuid(),venda_id uuid not null references public.vendas(id) on delete cascade,variacao_id uuid not null references public.produto_variacoes(id),produto_nome text not null,cor text not null,tamanho text not null,quantidade integer not null check(quantidade>0),preco_unitario numeric(12,2) not null check(preco_unitario>=0),subtotal numeric(12,2) not null);
create index operadores_cpf_idx on public.operadores(cpf); create index clientes_loja_cpf_idx on public.clientes(loja_id,cpf); create index variacoes_barcode_idx on public.produto_variacoes(loja_id,codigo_barras); create index variacoes_sku_idx on public.produto_variacoes(loja_id,sku); create index carts_open_idx on public.carrinhos_ativos(loja_id,status,updated_at desc); create index cart_items_cart_idx on public.carrinho_itens(carrinho_id); create index sales_store_date_idx on public.vendas(loja_id,created_at desc);
create or replace function public.current_operator_id() returns uuid language sql stable security definer set search_path=public as $$ select id from operadores where auth_user_id=auth.uid() and ativo $$;
create or replace function public.current_store_id() returns uuid language sql stable security definer set search_path=public as $$ select loja_id from operadores where auth_user_id=auth.uid() and ativo $$;
revoke all on function public.current_operator_id() from public; revoke all on function public.current_store_id() from public; grant execute on function public.current_operator_id() to authenticated; grant execute on function public.current_store_id() to authenticated;
alter table public.lojas enable row level security; alter table public.operadores enable row level security; alter table public.produtos enable row level security; alter table public.produto_variacoes enable row level security; alter table public.clientes enable row level security; alter table public.carrinhos_ativos enable row level security; alter table public.carrinho_itens enable row level security; alter table public.vendas enable row level security; alter table public.venda_itens enable row level security;
create policy loja_read on public.lojas for select to authenticated using(id=current_store_id()); create policy operador_read on public.operadores for select to authenticated using(loja_id=current_store_id());
create policy produto_access on public.produtos for all to authenticated using(loja_id=current_store_id()) with check(loja_id=current_store_id()); create policy variacao_access on public.produto_variacoes for all to authenticated using(loja_id=current_store_id()) with check(loja_id=current_store_id()); create policy cliente_access on public.clientes for all to authenticated using(loja_id=current_store_id()) with check(loja_id=current_store_id());
create policy carrinho_read on public.carrinhos_ativos for select to authenticated using(loja_id=current_store_id()); create policy carrinho_create on public.carrinhos_ativos for insert to authenticated with check(loja_id=current_store_id() and operador_id=current_operator_id()); create policy carrinho_update on public.carrinhos_ativos for update to authenticated using(loja_id=current_store_id()) with check(loja_id=current_store_id());
create policy carrinho_item_read on public.carrinho_itens for select to authenticated using(loja_id=current_store_id()); create policy carrinho_item_insert on public.carrinho_itens for insert to authenticated with check(loja_id=current_store_id() and exists(select 1 from carrinhos_ativos c where c.id=carrinho_id and c.loja_id=current_store_id() and c.status='aberto')); create policy carrinho_item_update on public.carrinho_itens for update to authenticated using(loja_id=current_store_id()) with check(loja_id=current_store_id()); create policy carrinho_item_delete on public.carrinho_itens for delete to authenticated using(loja_id=current_store_id());
create policy venda_read on public.vendas for select to authenticated using(loja_id=current_store_id()); create policy venda_item_read on public.venda_itens for select to authenticated using(exists(select 1 from vendas v where v.id=venda_id and v.loja_id=current_store_id()));
-- PIN hash is bcrypt. Put API gateway/Edge Function rate limiting in front of the public login RPC.
create or replace function public.login_operador(p_cpf text,p_pin text) returns table(id uuid,loja_id uuid,auth_email text) language plpgsql security definer set search_path=public,extensions as $$ begin if p_cpf !~ '^\d{11}$' or p_pin !~ '^\d{6}$' then return; end if; return query select o.id,o.loja_id,o.auth_email from operadores o where o.cpf=p_cpf and o.ativo and o.pin_hash=crypt(p_pin,o.pin_hash); end $$;
revoke all on function public.login_operador(text,text) from public; grant execute on function public.login_operador(text,text) to anon,authenticated;
create or replace function public.adicionar_item_carrinho(p_carrinho_id uuid,p_variacao_id uuid,p_quantidade integer default 1) returns void language plpgsql security definer set search_path=public as $$ declare s uuid; begin if auth.uid() is null or p_quantidade<1 then raise exception 'Operação inválida'; end if; select loja_id into s from carrinhos_ativos where id=p_carrinho_id and status='aberto' and loja_id=current_store_id(); if s is null then raise exception 'Carrinho indisponível'; end if; if not exists(select 1 from produto_variacoes where id=p_variacao_id and loja_id=s and ativo) then raise exception 'Variação inválida'; end if; insert into carrinho_itens(carrinho_id,loja_id,variacao_id,quantidade) values(p_carrinho_id,s,p_variacao_id,p_quantidade) on conflict(carrinho_id,variacao_id) do update set quantidade=carrinho_itens.quantidade+excluded.quantidade; update carrinhos_ativos set updated_at=now() where id=p_carrinho_id; end $$;
grant execute on function public.adicionar_item_carrinho(uuid,uuid,integer) to authenticated;
create or replace function public.finalizar_venda(p_carrinho_id uuid,p_cpf text,p_nome text,p_email text,p_forma_pagamento text) returns jsonb language plpgsql security definer set search_path=public as $$
declare c carrinhos_ativos; customer uuid; sale uuid; total numeric(12,2);
begin
 if auth.uid() is null then raise exception 'Não autenticado'; end if;
 select * into c from carrinhos_ativos where id=p_carrinho_id and status='aberto' and loja_id=current_store_id() for update;
 if not found then raise exception 'Carrinho indisponível'; end if;
 if not exists(select 1 from carrinho_itens where carrinho_id=c.id) then raise exception 'Carrinho vazio'; end if;
 if p_cpf is not null then if p_cpf !~ '^\d{11}$' or coalesce(trim(p_nome),'')='' then raise exception 'Dados do cliente inválidos'; end if; insert into clientes(loja_id,cpf,nome,email) values(c.loja_id,p_cpf,p_nome,nullif(p_email,'')) on conflict(loja_id,cpf) do update set nome=excluded.nome,email=excluded.email,updated_at=now() returning id into customer; end if;
 perform 1 from produto_variacoes v join carrinho_itens i on i.variacao_id=v.id where i.carrinho_id=c.id and v.estoque<i.quantidade for update of v; if found then raise exception 'Estoque insuficiente para um ou mais itens'; end if;
 select sum(i.quantidade*v.preco) into total from carrinho_itens i join produto_variacoes v on v.id=i.variacao_id where i.carrinho_id=c.id;
 insert into vendas(loja_id,operador_id,cliente_id,total,forma_pagamento,origem_carrinho_id) values(c.loja_id,c.operador_id,customer,total,p_forma_pagamento,c.id) returning id into sale;
 insert into venda_itens(venda_id,variacao_id,produto_nome,cor,tamanho,quantidade,preco_unitario,subtotal) select sale,v.id,p.nome,v.cor,v.tamanho,i.quantidade,v.preco,i.quantidade*v.preco from carrinho_itens i join produto_variacoes v on v.id=i.variacao_id join produtos p on p.id=v.produto_id where i.carrinho_id=c.id;
 update produto_variacoes v set estoque=v.estoque-i.quantidade from carrinho_itens i where i.carrinho_id=c.id and i.variacao_id=v.id; update carrinhos_ativos set status='finalizado',updated_at=now() where id=c.id;
 return jsonb_build_object('loja',(select jsonb_build_object('nome_fantasia',nome_fantasia,'cnpj',cnpj,'endereco',endereco,'telefone',telefone) from lojas where id=c.loja_id),'venda',jsonb_build_object('id',sale,'created_at',now(),'total',total,'forma_pagamento',p_forma_pagamento,'operador',(select nome from operadores where id=c.operador_id),'cliente_nome',(select nome from clientes where id=customer),'cliente_cpf',p_cpf,'itens',(select jsonb_agg(jsonb_build_object('nome',produto_nome,'cor',cor,'tamanho',tamanho,'quantidade',quantidade,'preco_unitario',preco_unitario) order by produto_nome) from venda_itens where venda_id=sale)));
end $$;
grant execute on function public.finalizar_venda(uuid,text,text,text,text) to authenticated;
create or replace function public.registrar_entrada_estoque(p_itens jsonb) returns jsonb language plpgsql security definer set search_path=public as $$ declare item jsonb; code text; qty integer; changed integer:=0; store uuid:=current_store_id(); vid uuid; begin if auth.uid() is null or store is null or jsonb_typeof(p_itens)<>'array' then raise exception 'Entrada inválida'; end if; for item in select value from jsonb_array_elements(p_itens) loop code:=item->>'codigo'; qty:=(item->>'quantidade')::integer; if qty<1 or qty>100000 then raise exception 'Quantidade inválida'; end if; select id into vid from produto_variacoes where loja_id=store and (codigo_barras=code or sku=code) and ativo for update; if vid is null then raise exception 'Código não localizado: %',code; end if; update produto_variacoes set estoque=estoque+qty where id=vid; changed:=changed+1; vid:=null; end loop; return jsonb_build_object('atualizados',changed); end $$;
grant execute on function public.registrar_entrada_estoque(jsonb) to authenticated;
